CREATE OR REPLACE FUNCTION pg_temp.expect_sqlstate(command text, expected_state text, label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN EXECUTE command; RAISE EXCEPTION '%: expected %, succeeded',label,expected_state; EXCEPTION WHEN OTHERS THEN IF SQLSTATE='P0001' THEN RAISE; END IF; IF SQLSTATE<>expected_state THEN RAISE EXCEPTION '%: expected %, got %',label,expected_state,SQLSTATE; END IF; END $$;
-- S3/S4/S15 static authority.
DO $$ BEGIN
 IF (SELECT data_type FROM information_schema.columns WHERE table_schema='public' AND table_name='reporting_statement_revisions' AND column_name='canonical_snapshot_json')<>'text' THEN RAISE EXCEPTION 'S15 canonical JSON must be TEXT'; END IF;
 IF (SELECT data_type FROM information_schema.columns WHERE table_schema='public' AND table_name='reporting_statement_revisions' AND column_name='semantic_hash')<>'character' OR (SELECT character_maximum_length FROM information_schema.columns WHERE table_schema='public' AND table_name='reporting_statement_revisions' AND column_name='semantic_hash')<>64 THEN RAISE EXCEPTION 'S15 semantic hash must be CHAR(64)'; END IF;
 IF EXISTS (SELECT 1 FROM pg_index i JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=ANY(i.indkey) WHERE n.nspname='public' AND t.relname='reporting_statement_revisions' AND a.attname='semantic_hash' AND i.indisunique) THEN RAISE EXCEPTION 'S15 semantic hash must not be unique'; END IF;
 IF (SELECT array_agg(e.enumlabel::text ORDER BY e.enumsortorder) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_enum e ON e.enumtypid=t.oid WHERE n.nspname='public' AND t.typname='ReportingStatementLifecycleState') IS DISTINCT FROM ARRAY['SUBMITTED','APPROVED','REJECTED','SUPERSEDED'] THEN RAISE EXCEPTION 'lifecycle enum contract'; END IF;
 IF (SELECT array_agg(e.enumlabel::text ORDER BY e.enumsortorder) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_enum e ON e.enumtypid=t.oid WHERE n.nspname='public' AND t.typname='ReportingStatementCommandType') IS DISTINCT FROM ARRAY['SUBMIT','APPROVE','REJECT'] THEN RAISE EXCEPTION 'command enum contract'; END IF;
 IF (SELECT array_agg(e.enumlabel::text ORDER BY e.enumsortorder) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_enum e ON e.enumtypid=t.oid WHERE n.nspname='public' AND t.typname='ReportingStatementHistoryEvent') IS DISTINCT FROM ARRAY['SUBMITTED','APPROVED','REJECTED','SUPERSEDED'] THEN RAISE EXCEPTION 'history enum contract'; END IF;
END $$;
