SELECT pg_temp.expect_sqlstate($q$INSERT INTO reporting_statement_revisions(id,series_id,predecessor_revision_id,snapshot_profile,serializer_version,canonical_snapshot_json,semantic_hash,as_of_instant) VALUES ('a5000000-0000-0000-0000-000000000026','a4000000-0000-0000-0000-000000000001','a5000000-0000-0000-0000-000000000005','P','v','{}','6666666666666666666666666666666666666666666666666666666666666666',now())$q$,'23505','predecessor unique');
INSERT INTO reporting_statement_revisions(id,series_id,supersedes_revision_id,snapshot_profile,serializer_version,canonical_snapshot_json,semantic_hash,as_of_instant) VALUES ('a5000000-0000-0000-0000-000000000027','a4000000-0000-0000-0000-000000000001','a5000000-0000-0000-0000-000000000003','P','v','{}','7777777777777777777777777777777777777777777777777777777777777777',now()),('a5000000-0000-0000-0000-000000000028','a4000000-0000-0000-0000-000000000001','a5000000-0000-0000-0000-000000000003','P','v','{}','8888888888888888888888888888888888888888888888888888888888888888',now());DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_constraint JOIN pg_class t ON t.oid=conrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND conname='reporting_statement_revisions_predecessor_revision_id_key' AND contype='u') THEN RAISE EXCEPTION 'S13 predecessor unique constraint missing'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND c.conname='reporting_statement_revision_predecessor_fkey' AND pg_get_constraintdef(c.oid) LIKE '%FOREIGN KEY (predecessor_revision_id, series_id)%REFERENCES reporting_statement_revisions(id, series_id)%') THEN RAISE EXCEPTION 'S13 predecessor composite FK missing'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND c.conname='reporting_statement_revision_supersedes_fkey' AND pg_get_constraintdef(c.oid) LIKE '%FOREIGN KEY (supersedes_revision_id, series_id)%REFERENCES reporting_statement_revisions(id, series_id)%') THEN RAISE EXCEPTION 'S13 supersedes composite FK missing'; END IF;
END $$;-- Part 2A: catalog contracts and history fixtures.
DO $$ DECLARE allowed text[]:=ARRAY['reporting_statement_series','reporting_statement_revisions','reporting_statement_revision_states','reporting_statement_revision_subjects','reporting_statement_commands','reporting_statement_histories']; BEGIN
 IF EXISTS(SELECT 1 FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relkind IN ('r','p') AND starts_with(t.relname,'reporting_statement_') AND NOT(t.relname=ANY(allowed))) OR (SELECT count(*) FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relkind IN ('r','p') AND t.relname=ANY(allowed))<>6 THEN RAISE EXCEPTION 'exact six Statement tables'; END IF;
 IF EXISTS(SELECT 1 FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND c.contype='f' AND t.relname=ANY(allowed) AND c.confdeltype<>'r') THEN RAISE EXCEPTION 'S12 Statement FK is not RESTRICT'; END IF;
 IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('reporting_statement_revisions','reporting_statement_commands','reporting_statement_histories') AND column_name='updated_at') THEN RAISE EXCEPTION 'immutable Statement rows have updated_at'; END IF;
 IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='reporting_statement_histories' AND column_name IN ('deleted_at','reversed_at','deleted_by')) THEN RAISE EXCEPTION 'S14 structural history boundary'; END IF;
 IF EXISTS(SELECT 1 FROM pg_trigger g JOIN pg_class t ON t.oid=g.tgrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relname=ANY(allowed) AND NOT g.tgisinternal) THEN RAISE EXCEPTION 'Statement tables must have no user-defined triggers'; END IF;
 IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='reporting_statement_revision_subjects' AND column_name IN ('is_zero_responsibility','zero_subject_marker','responsibility_state')) THEN RAISE EXCEPTION 'S16 sentinel forbidden'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relname='reporting_statement_revision_subjects' AND c.contype='p' AND pg_get_constraintdef(c.oid) LIKE '%PRIMARY KEY (revision_id, subject_id)%') THEN RAISE EXCEPTION 'S16 subject PK'; END IF;
 IF EXISTS(SELECT 1 FROM pg_index i JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=ANY(i.indkey) WHERE n.nspname='public' AND t.relname='reporting_statement_histories' AND i.indisunique AND array_length(i.indkey,1)=1 AND a.attname='command_id') THEN RAISE EXCEPTION 'history command must be nonunique'; END IF;
END $$;
