SELECT pg_temp.expect_sqlstate($q$DELETE FROM reporting_statement_commands WHERE id='a7000000-0000-0000-0000-000000000001'$q$,'23503','S12 command');-- Ordered pg_catalog contracts: conkey/confkey are expanded with ordinality, never hard-coded attnums.
CREATE OR REPLACE FUNCTION pg_temp.assert_statement_constraint(n text, kind "char", src text, cols text[], dst text DEFAULT NULL, dstcols text[] DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$ DECLARE c record; actual text[]; target text[]; BEGIN
 SELECT x.* INTO c FROM pg_constraint x JOIN pg_class r ON r.oid=x.conrelid JOIN pg_namespace rs ON rs.oid=r.relnamespace WHERE rs.nspname='public' AND x.conname=n AND r.relname=src; IF NOT FOUND OR c.contype<>kind THEN RAISE EXCEPTION 'constraint % missing/type/source mismatch',n; END IF;
 SELECT array_agg(a.attname ORDER BY u.ord) INTO actual FROM unnest(c.conkey) WITH ORDINALITY u(attnum,ord) JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=u.attnum; IF actual IS DISTINCT FROM cols THEN RAISE EXCEPTION 'constraint % source columns %, expected %',n,actual,cols; END IF;
 IF dst IS NOT NULL THEN IF (SELECT r.relname FROM pg_class r JOIN pg_namespace ns ON ns.oid=r.relnamespace WHERE ns.nspname='public' AND r.oid=c.confrelid) IS DISTINCT FROM dst THEN RAISE EXCEPTION 'constraint % target mismatch',n; END IF; SELECT array_agg(a.attname ORDER BY u.ord) INTO target FROM unnest(c.confkey) WITH ORDINALITY u(attnum,ord) JOIN pg_attribute a ON a.attrelid=c.confrelid AND a.attnum=u.attnum; IF target IS DISTINCT FROM dstcols THEN RAISE EXCEPTION 'constraint % target columns %, expected %',n,target,dstcols; END IF; END IF;
END $$;
