INSERT INTO reporting_statement_revision_states VALUES ('a5000000-0000-0000-0000-000000000003','a4000000-0000-0000-0000-000000000001','REJECTED','d6000000-0000-0000-0000-000000000001',now()),('a5000000-0000-0000-0000-000000000004','a4000000-0000-0000-0000-000000000001','SUBMITTED','d6000000-0000-0000-0000-000000000002',now());
DO $$ DECLARE n int; st "ReportingStatementLifecycleState"; tok uuid; BEGIN UPDATE reporting_statement_revision_states SET lifecycle_state='REJECTED',lifecycle_token='d6000000-0000-0000-0000-000000000003',updated_at=now() WHERE revision_id='a5000000-0000-0000-0000-000000000004' AND series_id='a4000000-0000-0000-0000-000000000001' AND lifecycle_state='SUBMITTED' AND lifecycle_token='d6000000-0000-0000-0000-000000000002'; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'S18 exact CAS'; END IF; UPDATE reporting_statement_revision_states SET lifecycle_state='APPROVED' WHERE revision_id='a5000000-0000-0000-0000-000000000004' AND series_id='a4000000-0000-0000-0000-000000000001' AND lifecycle_state='SUBMITTED' AND lifecycle_token='d6000000-0000-0000-0000-000000000002'; GET DIAGNOSTICS n=ROW_COUNT; IF n<>0 THEN RAISE EXCEPTION 'S18 stale CAS'; END IF; SELECT lifecycle_state,lifecycle_token INTO st,tok FROM reporting_statement_revision_states WHERE revision_id='a5000000-0000-0000-0000-000000000004'; IF st<>'REJECTED' OR tok<>'d6000000-0000-0000-0000-000000000003' THEN RAISE EXCEPTION 'S18 final CAS'; END IF; IF NOT EXISTS(SELECT 1 FROM reporting_statement_revisions r JOIN reporting_statement_revision_states x ON x.revision_id=r.id WHERE r.id='a5000000-0000-0000-0000-000000000001' AND x.lifecycle_state='SUPERSEDED') THEN RAISE EXCEPTION 'S17 superseded terminal readability'; END IF; IF NOT EXISTS(SELECT 1 FROM reporting_statement_revisions r JOIN reporting_statement_revision_states x ON x.revision_id=r.id WHERE r.id='a5000000-0000-0000-0000-000000000003' AND x.lifecycle_state='REJECTED') THEN RAISE EXCEPTION 'S17 rejected terminal readability'; END IF; END $$;
DO $$ DECLARE n text; expected text; predicate text; BEGIN FOREACH n IN ARRAY ARRAY['reporting_statement_one_submitted_per_series','reporting_statement_one_approved_per_series'] LOOP expected:=CASE WHEN n LIKE '%submitted%' THEN 'SUBMITTED' ELSE 'APPROVED' END; SELECT pg_get_expr(i.indpred,i.indrelid) INTO predicate FROM pg_index i JOIN pg_class x ON x.oid=i.indexrelid JOIN pg_namespace xn ON xn.oid=x.relnamespace JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace tn ON tn.oid=t.relnamespace JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=ANY(i.indkey) WHERE xn.nspname='public' AND tn.nspname='public' AND x.relname=n AND t.relname='reporting_statement_revision_states' AND i.indisunique AND array_length(i.indkey,1)=1 AND a.attname='series_id'; IF predicate IS NULL OR position('lifecycle_state' IN lower(predicate))=0 OR position(expected IN predicate)=0 THEN RAISE EXCEPTION 'S19 index %',n; END IF; END LOOP; END $$;DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='reporting_statement_revision_subjects' AND column_name IN ('revision_id','subject_id') AND is_nullable<>'NO') OR (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='reporting_statement_revision_subjects' AND column_name IN ('revision_id','subject_id'))<>2 THEN RAISE EXCEPTION 'S16 RevisionSubject columns must be NOT NULL'; END IF;
END $$;
